-- Imports 123 unique ride-on car catalogue records extracted from:
-- kids car price list(7) (1).pdf
--
-- Safe to re-run: it only inserts previously unseen import SKUs.
-- Products are intentionally saved as Draft, with stock and public selling price set to 0.
-- The PDF provides FOB USD, not Musa Traders retail prices. Set retail prices, stock and
-- product images from Admin -> Products before publishing a product.
-- Requires: 20261009_ride_on_car_catalog.sql (and this script creates the category if missing).

begin;

-- Make the target category available even if the standalone category migration was not run.
insert into categories(name,slug,description,image_url,status,sort_order,show_in_menu,show_on_homepage)
values ('Ride-on Cars','ride-on-cars','Battery-powered ride-on cars, jeeps, bikes and accessories for children.','/category-icons/ride-on-cars.svg','active',0,true,true)
on conflict(slug) do update set
  name=excluded.name, description=excluded.description,
  image_url=coalesce(categories.image_url,excluded.image_url), status='active',
  show_in_menu=true, show_on_homepage=true;

do $$
begin
  if not exists (select 1 from information_schema.columns where table_schema='public' and table_name='products' and column_name='model_number') then
    raise exception 'Run supabase/migrations/20261009_ride_on_car_catalog.sql before this import.';
  end if;
end $$;

-- Correct products imported by an earlier version of this file as well.
-- Category stays Ride-on Cars; product titles contain only their actual model/name.
update products
set name=regexp_replace(name, '^Ride-on Car[[:space:]]+', '')
where sku like 'IMPORT-RIDEON-%' and name like 'Ride-on Car %';

