insert into products(
  name,slug,sku,description,regular_price,status,model_number,product_dimensions_cm,
  carton_dimensions_cm,cbm,net_weight_kg,gross_weight_kg,pieces_per_carton,quantity_40hq,
  fob_usd,import_notes,technical_specs,tags
)
select
  name,slug,sku,description,0,'draft',model_number,product_dimensions_cm,
  carton_dimensions_cm,cbm,net_weight_kg,gross_weight_kg,pieces_per_carton,quantity_40hq,
  fob_usd,
  'Imported from Kids Car Price List PDF, page '||source_page||'. FOB USD is supplier reference only; set Musa Traders retail price before publishing.',
  jsonb_build_object(
    'source','kids car price list(7) (1).pdf',
    'source_page',source_page,
    'available_colours',available_colours,
    'supplier_specification',description,
    'supplier_options',source_options
  ),
  array['ride-on-car','imported-catalogue']
from source
on conflict do nothing;

-- New rows from the source list use the same clean product-title rule.
update products
set name=regexp_replace(name, '^Ride-on Car[[:space:]]+', '')
where sku like 'IMPORT-RIDEON-%' and name like 'Ride-on Car %';

